constexpr uint32_t CONSOLE_BAUD_RATE = 921600;

// Longest command line, except load_image.
constexpr size_t CONSOLE_LINE_CAPACITY = 200;

// Longest load_image line: 2 hexadecimal digits per byte of MAXIMUM_IMAGE_SIZE, plus 32 characters
// for the command word "load_image " and a margin.
constexpr size_t IMAGE_LINE_CAPACITY = 2226;

// Path of the console on the WebSocket server of a node.
constexpr const char *CONSOLE_WEBSOCKET_PATH = "/console";

// IPv4 address of a node on its own access point, where the WebSocket server listens.
constexpr uint8_t ACCESS_POINT_ADDRESS[] = {192, 168, 4, 1};

