// The cmd field of an error for a line that names no command keeps at most this many characters of
// its first word.
constexpr size_t ERROR_COMMAND_WORD_LENGTH = 15;

// Checks that run before a form of a command, in this order: rejectedDuringRun: no run of the node
// is in progress, or else busy; rejectedDuringEcho: no echo of the node waits for its reply, or
// else busy; needsRadio: the radio started at boot, or else radio_failure "radio not started".
enum class CommandPrecondition : uint8_t {
  RejectedDuringRun,
  RejectedDuringEcho,
  NeedsRadio,
};

// A precondition and the error a command answers when the node does not meet it.
struct CommandPreconditionCheck {
  CommandPrecondition precondition;
  ErrorReason refusalReason;
  const char *refusalDetail; // or nullptr
};

// Every precondition, in the order of the checks.
constexpr CommandPreconditionCheck COMMAND_PRECONDITIONS[] = {
    {CommandPrecondition::RejectedDuringRun, ErrorReason::Busy, nullptr},
    {CommandPrecondition::RejectedDuringEcho, ErrorReason::Busy, nullptr},
    {CommandPrecondition::NeedsRadio, ErrorReason::RadioFailure, "radio not started"},
};

// The preconditions of a form, as one bit per precondition.
using CommandPreconditions = uint8_t;
constexpr CommandPreconditions NO_PRECONDITIONS = 0;
constexpr CommandPreconditions preconditionFlag(CommandPrecondition precondition) {
  return static_cast<CommandPreconditions>(1 << static_cast<uint8_t>(precondition));
}
constexpr CommandPreconditions REJECTED_DURING_RUN =
    preconditionFlag(CommandPrecondition::RejectedDuringRun);
constexpr CommandPreconditions REJECTED_DURING_ECHO =
    preconditionFlag(CommandPrecondition::RejectedDuringEcho);
constexpr CommandPreconditions NEEDS_RADIO = preconditionFlag(CommandPrecondition::NeedsRadio);

// What a form of a command does; the firmware binds a handler to each action.
enum class CommandAction : uint8_t {
  ListCommands,
  ReportStatus,
  ReportRadio,
  ResetRadio,
  ChangeRadio,
  RequestEcho,
  StopRun,
  StartRun,
  EnableWireless,
  DisableWireless,
  ResendLastFrame,
  ReleasePresence,
  HoldPresence,
  LoadRegisters,
  LoadImage,
  ActivateAvailableVersion,
  ChangeFragmentSize,
  ReportProgram,
};

// One way of calling a command: the arguments it takes and the checks before its action.
struct CommandForm {
  const char *selector; // first argument that selects the form, or nullptr for any
  uint8_t minimumArguments;
  uint8_t maximumArguments;
  CommandPreconditions preconditions;
  CommandAction action;
};

constexpr size_t MAXIMUM_COMMAND_FORMS = 3;

// A console command. A line takes the first form whose selector and argument count match it;
// a line that matches none is a usage error.
struct ConsoleCommand {
  const char *name;
  const char *usage; // help lists it, and usage errors carry it as their detail
  size_t maximumLineLength;
  uint8_t formCount;
  CommandForm forms[MAXIMUM_COMMAND_FORMS];
};

