// -------------------------------------------------------------------------------------------------
// Timings (docs/protocol/frame.md and docs/protocol/console.md)

// A node sends a HELLO every period, give or take the jitter at random.
constexpr uint32_t HELLO_PERIOD_MS = 10000;
constexpr uint32_t HELLO_JITTER_MS = 2000;

// The first HELLO after a boot or a suspension leaves within this window.
constexpr uint32_t FIRST_HELLO_MINIMUM_DELAY_MS = 1000;
constexpr uint32_t FIRST_HELLO_MAXIMUM_DELAY_MS = 3000;

// A neighbor leaves the table when no packet of it arrives for this long; see isNeighborExpired.
constexpr uint32_t NEIGHBOR_EXPIRY_MS = 60000;

// True when a neighbor last heard elapsedMillis ago has expired, from NEIGHBOR_EXPIRY_MS on.
constexpr bool isNeighborExpired(uint32_t elapsedMillis) {
  return elapsedMillis >= NEIGHBOR_EXPIRY_MS;
}

// Limits, in seconds, of the hold of the HELLO messages that presence off accepts.
constexpr uint32_t MINIMUM_PRESENCE_HOLD_S = 1;
constexpr uint32_t MAXIMUM_PRESENCE_HOLD_S = 3600;

// Margin of the echo_lost and run_end deadlines; see the functions below.
constexpr uint32_t RESPONSE_MARGIN_MS = 1000;

// Time from the start of an echo request on the air until the requester reports echo_lost: twice
// the time on air of the request in whole milliseconds, rounded up, plus the margin
// (RESPONSE_MARGIN_MS).
constexpr uint32_t echoLossDeadlineMillis(uint32_t requestTimeOnAirMicros) {
  return 2 * ((requestTimeOnAirMicros + 999) / 1000) + RESPONSE_MARGIN_MS;
}

// Time from a TEST packet of a run until the receiver ends the run with run_end when no other
// arrives: twice the sum of the interval and the time on air of the packet in whole milliseconds,
// rounded up, plus the margin (RESPONSE_MARGIN_MS).
constexpr uint32_t runReceptionDeadlineMillis(uint32_t intervalMillis,
                                              uint32_t packetTimeOnAirMicros) {
  return 2 * (intervalMillis + (packetTimeOnAirMicros + 999) / 1000) + RESPONSE_MARGIN_MS;
}

// Added to the burst end and to the report repeat deadlines.
constexpr uint32_t TRANSFER_MARGIN_MS = 500;

